import { EX_winP,EX_winA,drawBitmapText, measureBitmapText } from "./winUtils.js";
import { gAttrVisStyle } from "./gAttr.js";

let zip = rows=>rows[0].map((_,c)=>rows.map(row=>row[c]))


class ordNode{
}

class ordSingleNode extends ordNode{
    constructor(child,padding){
        super();
        this._OChild = child;
        this._OPadding = padding;
    }

    getChildren(winA){ 
        return [[this._OChild], 
        [new EX_winA(winA.getP(), 
            [...zip([winA.getTopLeft(),[+this._OPadding[0],+this._OPadding[1]]]).map(t => t[0] + t[1]),
        winA.getSize()[0]- this._OPadding[0]*2,
        winA.getSize()[1]- this._OPadding[1]*2])]];
    }
}

class ordColumnsV extends ordNode{
    constructor(children, unitP){
        super();
        //2 EX_winA Area
        this._OChild = [children[0],children[1]];
        this._OProp = unitP;
    }

    getChildren(winA){ return [this._OChild, 
        [new EX_winA(winA.getP(), [...winA.getTopLeft(),winA.getSize()[0]*this._OProp,winA.getSize()[1]]), 
        new EX_winA(winA.getP(), [...zip([winA.getTopLeft(),[winA.getSize()[0]*this._OProp,0]]).map(t => t[0] + t[1]),winA.getSize()[0]*(1-this._OProp),winA.getSize()[1]])]];}
}

class ordColumnsH extends ordNode{
    constructor(children, unitP){
        super();
        this._OChild = [children[0],children[1]];
        this._OProp = unitP;
    }

    getChildren(winA){ return [this._OChild, 
        [new EX_winA(winA.getP(), [...winA.getTopLeft(),winA.getSize()[0],winA.getSize()[1]*this._OProp]), 
        new EX_winA(winA.getP(), [...zip([winA.getTopLeft(),[0,winA.getSize()[1]*this._OProp]]).map(t => t[0] + t[1]),winA.getSize()[0],winA.getSize()[1]*(1-this._OProp)])]];}
}

class ordLeaf{
    getChildren(winA){ return [];} //Is Leaf
}

class ordImage extends ordLeaf {
    constructor(base64) {
        super();
        this._OImg = new Image();
        this._OImg.src = base64.startsWith("data:") ? base64 : `data:image/png;base64,${base64}`;
    }
    draw(ctx, winA) {
        if (this._OImg.complete) ctx.drawImage(this._OImg, ...winA.getRect().slice(0, 2));
    }
}
class ordText extends ordLeaf{
    constructor(txt, size, color){super(); this._OTxt = txt;  this._OSize= size; this._OColor = color;}

    draw(ctx, winA){
        //ctx.font = this._OFont;
        ctx.fillStyle = this._OColor;

        let a = this._OTxt.split(/\r?\n/);
        let tOffset =  gAttrVisStyle["BASE"].winBarHeight;
        for(let i = 0; i < a.length; i++){
            drawBitmapText(ctx, a[i],  winA.getRect()[0],winA.getRect()[1]+ tOffset,this._OSize, this._OColor);
            if(i+1 < this._OTxt.length)
                tOffset +=  gAttrVisStyle["BASE"].winRendLineSpace + measureBitmapText(a[i+1],this._OSize).height;
        }
    }
}

class ordColor extends ordLeaf{
    constructor(color){ super(); this._OColor = color;}

    draw(ctx, winA){
        ctx.fillStyle = this._OColor;
        ctx.fillRect(...winA.getRect());
    }
}

class EX_winExec{
    constructor(winP,node){
        this.wWinA = new EX_winA(winP,winP.getRect());
    
        
        this._ETopNode = node;
    }

    recChildCall(ctx,n,winA){
        const [c, w] = n.getChildren(winA);
        for(let i = 0; i < c.length; i++){
            
            if(c[i] instanceof ordLeaf)
                c[i].draw(ctx, w[i])
            else
                this.recChildCall(ctx,c[i],w[i]);
        }this.wWinA
    }

    draw(ctx){ 
        this.wWinA.reset();
        this.recChildCall(ctx, this._ETopNode, this.wWinA);
    }
}


function winFactoryEx(strRunContent, winP){
    switch(strRunContent){
        case "wEMain": return new EXP_wEMain(winP);
        case "wEProjects": return new EXP_wEProjects(winP);
        case "wEExperince": return new EXP_wEExperience(winP);
        case "wECreatura": return new EXP_wECreatura(winP);
        case "wEEducation": return new EXP_wEEducation(winP);
        case "wEContact": return new EXP_wEContact(winP);
        case "wELanguage": return new EXP_wELanguages(winP);
    }
}

